72	 it('moving cavalry gains impact while stops and sharp turns lose the charge',()=>{
73	  const trial=(motion:'stationary'|'charge'|'stop'|'turn')=>{const s=fixture(),cavalry=unit(s,0,'cavalry',18.5,24.5),target=unit(s,1,'melee',26,24.5);target.facing=4;cavalry.cooldown=100;refreshVisibility(s);if(motion!=='stationary'){issueCommand(s,0,{type:'move',ids:[cavalry.id],x:25.1,y:24.5});advance(s,1.8);expect(cavalry.tactics!.charge!.distance).toBeGreaterThan(4);if(motion==='stop'){issueCommand(s,0,{type:'hold',ids:[cavalry.id]});advance(s,1.5);}if(motion==='turn'){issueCommand(s,0,{type:'move',ids:[cavalry.id],x:cavalry.x,y:cavalry.y-2});advance(s,.4);}}else cavalry.x=25.1;const hp=target.hp;fire(s,cavalry,target,.3);return hp-target.hp;};
74	  expect(trial('charge')).toBeGreaterThan(trial('stationary')*1.5);expect(trial('stop')).toBeLessThan(trial('charge'));expect(trial('turn')).toBeLessThan(trial('charge'));
