76	 it('frontal braced pikes cancel charge and hurt the rider; a rear charge retains impact',()=>{
77	  const trial=(facing:number)=>{const s=fixture(),rider=unit(s,0,'cavalry',18.5,24.5),pike=unit(s,1,'spear',26,24.5);pike.facing=facing;rider.cooldown=100;refreshVisibility(s);issueCommand(s,0,{type:'move',ids:[rider.id],x:25.1,y:24.5});advance(s,1.8);const hp=pike.hp,riderHp=rider.hp;fire(s,rider,pike,.05);return {loss:hp-pike.hp,riderLoss:riderHp-rider.hp,charge:rider.tactics!.charge!.distance};};
78	  const front=trial(4),rear=trial(0);expect(front.loss).toBeCloseTo(17);expect(front.riderLoss).toBeGreaterThan(10);expect(front.charge).toBe(0);expect(rear.loss).toBeGreaterThan(front.loss*1.5);expect(rear.riderLoss).toBe(0);

127	export function updateCharge(s:GameState,e:Entity,from:Vec,dt:number):void {
128	 if(e.role!=='cavalry'||e.illusion)return;const t=initializeTactics(s,e),moved=distance(from,e),c=t.charge??={distance:0,heading:e.facing,lastMovedAt:s.time};
129	 if(moved>dt*.5){const turn=Math.abs(Math.atan2(Math.sin((e.facing-c.heading)*Math.PI/4),Math.cos((e.facing-c.heading)*Math.PI/4)));if(turn>Math.PI/4+.01)c.distance=0;c.distance=Math.min(TACTICS.chargeDistance,c.distance+moved);c.heading=e.facing;c.lastMovedAt=s.time;}
130	
131	}
132	export function ageCharge(s:GameState,e:Entity,dt:number):void {const c=e.tactics?.charge;if(c&&s.time-c.lastMovedAt>.25)c.distance=Math.max(0,c.distance-dt*5);}
133	export function cavalryImpact(s:GameState,source:Entity,target:Entity):{factor:number;pikeDamage:number} {
134	 if(source.role!=='cavalry'||source.illusion)return {factor:1,pikeDamage:0};
135	 const c=initializeTactics(s,source).charge,turn=c?Math.abs(Math.atan2(Math.sin((source.facing-c.heading)*Math.PI/4),Math.cos((source.facing-c.heading)*Math.PI/4))):0,distanceCharged=turn>Math.PI/4+.01?0:c?.distance??0,charged=distanceCharged>=1.5,front=facingDamageFactor(source,target)===1,braced=target.kind==='unit'&&target.role==='spear'&&target.order.type==='hold'&&front;
136	 if(c)c.distance=0;
137	 return braced&&charged?{factor:1,pikeDamage:TACTICS.pikeReturn*(distanceCharged/TACTICS.chargeDistance)}:{factor:1+TACTICS.chargeBonus*(distanceCharged/TACTICS.chargeDistance),pikeDamage:0};
